def main():
    app=load(APP_ASSET); patch=load(PATCH_ASSET)
    if app!=patch: raise SystemExit('app/patch differ before batch8')
    by={s['id']:s for s in app['scenarios']}
    for sid,route in ROUTES.items():
        s=by[sid]; apply_route(s,**route)
        s.setdefault('actions',[{}])[0].update({'sourceBound':False,'riskClass':'normal','userFacingPolicy':'TRIAGE_ONLY_NO_REPAIR'})
        s['sourceAudit']={'auditedAt':V,'scope':'p0_msud_batch8','status':'IMPROVE'}
        if sid in EARLY:
            addref(s,R1); addref(s,LEGACY); old_historical(s)
            s['sourceAgeNote']='Повторный аудит 26.09.2026: ранний МСУД-Н. Заводское РЭ используется как техническая база; старые памятки — только для симптомов. Обозначения защит/датчиков между исполнениями могут различаться и требуют схемы конкретного электровоза.'
        else:
            addref(s,LATE_TECH); addref(s,LATE_2026)
            s['sourceAgeNote']='Повторный аудит 26.09.2026: только позднее поосное исполнение МСУД-015. Алгоритмы и набор сигналов зависят от профиля и версии ПО; эксплуатационные материалы 2026 года используются как cross-check, не как нормативное разрешение действий.'
    if len(app['scenarios'])!=136: raise SystemExit('scenario count changed')
    dump(APP_ASSET,app); dump(PATCH_ASSET,app)
    if APP_ASSET.read_bytes()!=PATCH_ASSET.read_bytes(): raise SystemExit('app/patch mismatch')
    print('ERMAK_P0_MSUD_BATCH8='+','.join(sorted(ROUTES)))

if __name__=='__main__': main()
